import { FileText, Search, Plus } from "lucide-react";
import { useNavigate, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import axios from "axios";

export default function Consult() {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedPriority, setSelectedPriority] = useState("all");
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch consultations from backend
  const fetchPatients = async () => {
    try {
      const response = await axios.get("/api/consults"); // backend endpoint
      setPatients(response.data.data); // adjust if your backend structure differs
      setLoading(false);
    } catch (error) {
      console.error("Failed to fetch consultations:", error);
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPatients();
  }, []);

  // Send consult to radiologist
  const handleSendToRadiologist = async (id) => {
    try {
      await axios.put(`/api/consults/${id}/send`);
      fetchPatients(); // refresh list after sending
    } catch (error) {
      console.error("Failed to send to radiologist:", error);
    }
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'critical': return 'text-red-400 bg-red-400/10 border-red-400';
      case 'high': return 'text-orange-400 bg-orange-400/10 border-orange-400';
      case 'medium': return 'text-yellow-400 bg-yellow-400/10 border-yellow-400';
      case 'low': return 'text-green-400 bg-green-400/10 border-green-400';
      default: return 'text-gray-400 bg-gray-400/10 border-gray-400';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'urgent': return 'bg-red-500';
      case 'pending': return 'bg-yellow-500';
      case 'reviewed': return 'bg-green-500';
      default: return 'bg-gray-500';
    }
  };

  const filteredPatients = patients.filter(patient => {
    const matchesSearch = 
      patient.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      patient.patientId.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (patient.finding?.toLowerCase() || '').includes(searchTerm.toLowerCase());
    const matchesPriority = selectedPriority === 'all' || patient.priority === selectedPriority;
    return matchesSearch && matchesPriority;
  });

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-cyan-900 text-white text-lg">
        Loading consultations...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-cyan-900">
      {/* Header */}
      <header className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <div className="bg-green-500 p-2 rounded-lg mr-3">
                <FileText className="h-6 w-6 text-white" />
              </div>
              <h1 className="text-xl font-bold text-white">MedVision AI Lab</h1>
            </div>
            <nav className="flex space-x-8">
              <Link to="/" className="text-gray-300 hover:text-white font-medium px-3 py-2">
                Uploads
              </Link>
              <button className="text-green-400 font-semibold border-b-2 border-green-400 px-3 py-2">
                Diagnostic Analysis
              </button>
              <Link to="/consult" className="text-gray-300 hover:text-white font-medium px-3 py-2">
                Consult
              </Link>
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Page Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2">Specialist Consultation</h1>
          <p className="text-gray-400">Request expert review for complex cases and second opinions</p>
        </div>

        {/* Statistics Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-gray-800 rounded-2xl p-6">
            <div className="text-2xl font-bold text-white mb-2">{patients.length}</div>
            <div className="text-gray-400 text-sm">Total Cases</div>
          </div>
          <div className="bg-gray-800 rounded-2xl p-6">
            <div className="text-2xl font-bold text-red-400 mb-2">
              {patients.filter(p => p.priority === 'critical' || p.priority === 'high').length}
            </div>
            <div className="text-gray-400 text-sm">Urgent Cases</div>
          </div>
          <div className="bg-gray-800 rounded-2xl p-6">
            <div className="text-2xl font-bold text-yellow-400 mb-2">
              {patients.filter(p => p.status === 'pending').length}
            </div>
            <div className="text-gray-400 text-sm">Pending Review</div>
          </div>
          <div className="bg-gray-800 rounded-2xl p-6">
            <div className="text-2xl font-bold text-green-400 mb-2">
              {patients.filter(p => p.status === 'reviewed').length}
            </div>
            <div className="text-gray-400 text-sm">Completed</div>
          </div>
        </div>

        {/* Controls */}
        <div className="flex flex-col sm:flex-row gap-4 mb-6">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-5 w-5" />
            <input
              type="text"
              placeholder="Search patients, conditions, or IDs..."
              className="w-full bg-gray-800 text-white pl-10 pr-4 py-3 rounded-xl border border-gray-600 focus:border-green-400 focus:outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-3">
            <select 
              value={selectedPriority}
              onChange={(e) => setSelectedPriority(e.target.value)}
              className="bg-gray-800 text-white px-4 py-3 rounded-xl border border-gray-600 focus:border-green-400 focus:outline-none"
            >
              <option value="all">All Priorities</option>
              <option value="critical">Critical</option>
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
            <Link to="/radiologistconsult" className="bg-green-500 text-white px-6 py-3 rounded-xl font-semibold hover:bg-green-600 transition-colors flex items-center">
              <Plus className="h-5 w-5 mr-2" />
              New Consultation
            </Link>
          </div>
        </div>

        {/* Patient List */}
        <div className="bg-gray-800 rounded-2xl shadow-xl overflow-hidden">
          {/* Table Header */}
          <div className="grid grid-cols-12 gap-4 px-6 py-4 bg-gray-750 border-b border-gray-700 text-gray-400 font-semibold text-sm">
            <div className="col-span-4">Patient Information & Scan</div>
            <div className="col-span-2">Clinical Details</div>
            <div className="col-span-2">AI Findings</div>
            <div className="col-span-1">Priority</div>
            <div className="col-span-3">Actions</div>
          </div>

          {/* Patient Rows */}
          <div className="divide-y divide-gray-700">
            {filteredPatients.map((patient) => (
              <div key={patient._id} className="grid grid-cols-12 gap-4 px-6 py-4 hover:bg-gray-750 transition-colors">
                <div className="col-span-4">
                  <div className="text-white font-semibold">{patient.patientName}</div>
                  <div className="text-gray-400 text-sm">{patient.patientId}</div>
                  <div className="text-gray-400 text-sm">{patient.age} yrs, {patient.gender}</div>
                </div>
                <div className="col-span-2 text-gray-400">{patient.symptoms}</div>
                <div className="col-span-2 text-gray-400">{patient.finding}</div>
                <div className={`col-span-1 text-center border px-2 py-1 rounded-xl text-sm font-semibold ${getPriorityColor(patient.priority)}`}>
                  {patient.priority}
                </div>
                <div className="col-span-3 flex gap-2">
                  <button
                    onClick={() => handleSendToRadiologist(patient._id)}
                    className="bg-green-500 text-white px-3 py-1 rounded hover:bg-green-600"
                  >
                    Send
                  </button>
                  {/* Optional Edit/Delete buttons */}
                  {/* <button className="bg-yellow-500 text-white px-3 py-1 rounded hover:bg-yellow-600">Edit</button>
                  <button className="bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600">Delete</button> */}
                </div>
              </div>
            ))}
          </div>

          {filteredPatients.length === 0 && (
            <div className="text-center py-12">
              <div className="text-gray-400 text-lg">No cases found</div>
              <div className="text-gray-500 text-sm mt-2">Try adjusting your search or filters</div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
